import networkx as nx

def solve():
    M = set()
    for a in range(200):
        for b in range(200):
            val = 11*a + 20*b
            if val < 1000:
                M.add(val)

    U = [i for i in range(190) if i not in M]

    # Comparability graph: edge if x < y or y < x
    G = nx.Graph()
    G.add_nodes_from(U)
    for x in U:
        for y in U:
            if x != y and (y - x) in M:
                G.add_edge(x, y)

    # The number of lower sets is the number of antichains.
    # An antichain is an independent set in the comparability graph.
    # Let's check the connected components of the comparability graph.
    components = list(nx.connected_components(G))
    print(f"Number of components: {len(components)}")
    for i, comp in enumerate(components):
        print(f"Component {i} size: {len(comp)}")

solve()

